public class MainActivity extends Activity {
 private SessionService session;
 private TextView status,monitorStatus,settingsStatus;
 private Button scrollMode;
 private AlertDialog diagnosticsDialog;
 private LinearLayout confirmation;
 private Pad pad;
 private final String[] orientations={"Landscape 0°","Portrait 90°","Landscape 180°","Portrait 270°"};
 private final ServiceConnection connection=new ServiceConnection(){public void onServiceConnected(ComponentName n,IBinder b){session=((SessionService.LocalBinder)b).get();session.listener=()->refresh();session.ensureDesktop();refresh();}public void onServiceDisconnected(ComponentName n){session=null;refresh();}};
 @Override public void onCreate(Bundle state){super.onCreate(state);getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);
  LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(12),dp(8),dp(12),dp(8));root.setBackgroundColor(Color.rgb(15,23,42));
  LinearLayout header=row(root);header.setGravity(Gravity.CENTER_VERTICAL);TextView title=label("DexDroid",23);header.addView(title,new LinearLayout.LayoutParams(0,dp(48),1));title.setGravity(Gravity.CENTER_VERTICAL);ImageButton options=new ImageButton(this);options.setImageResource(R.drawable.ic_settings);options.setBackgroundColor(Color.TRANSPARENT);options.setContentDescription("Options");options.setTooltipText("Options");header.addView(options,new LinearLayout.LayoutParams(dp(48),dp(48)));options.setOnClickListener(v->options());
  monitorStatus=label("Checking monitor…",18);monitorStatus.setPadding(dp(12),dp(10),dp(12),dp(10));monitorStatus.setTypeface(null,Typeface.BOLD);root.addView(monitorStatus,new LinearLayout.LayoutParams(-1,-2));status=label("Connecting controller…",12);status.setMaxLines(2);root.addView(status,new LinearLayout.LayoutParams(-1,dp(38)));
  LinearLayout top=row(root);iconButton(top,R.drawable.ic_apps,"Apps",this::apps);iconButton(top,R.drawable.ic_rotation,"Rotate",this::rotation);iconButton(top,R.drawable.ic_back,"Back",()->{if(session!=null){session.log("Back button pressed");session.key(KeyEvent.KEYCODE_BACK);}});
  LinearLayout actions=row(root);scrollMode=button(actions,"Scroll mode",this::scrollMode);iconButton(actions,R.drawable.ic_speed,"Speed",this::scrollSpeed);iconButton(actions,R.drawable.ic_save,"Save app",()->{if(session!=null){pad.cancel();session.saveAppSettings();}});iconButton(actions,R.drawable.ic_reset,"Reset app",()->{if(session!=null){pad.cancel();session.resetAppSettings();}});
  settingsStatus=label("Launch an app to view its settings",12);settingsStatus.setPadding(dp(10),dp(8),dp(10),dp(8));settingsStatus.setBackgroundColor(Color.rgb(30,41,59));root.addView(settingsStatus,new LinearLayout.LayoutParams(-1,-2));
  confirmation=row(root);button(confirmation,"Keep",()->{if(session!=null)session.confirm(true);});button(confirmation,"Revert",()->{if(session!=null)session.confirm(false);});confirmation.setVisibility(View.GONE);
  pad=new Pad();pad.setTag("touchpad");root.addView(pad,new LinearLayout.LayoutParams(-1,0,1));TextView help=label("Slide: pointer · Tap: click\nTwo fingers: scroll / pinch · Three fingers →: Back",12);root.addView(help);setContentView(root);
  bindService(new Intent(this,SessionService.class),connection,BIND_AUTO_CREATE);
 }
 private int dp(float value){return Math.round(value*getResources().getDisplayMetrics().density);}
 private TextView label(String text,int size){TextView v=new TextView(this);v.setText(text);v.setTextSize(size);v.setTextColor(Color.WHITE);return v;}
 private LinearLayout row(LinearLayout root){LinearLayout row=new LinearLayout(this);root.addView(row,new LinearLayout.LayoutParams(-1,-2));return row;}
 private Button button(LinearLayout row,String text,Runnable action){Button b=new Button(this);b.setText(text);b.setTextSize(12);b.setTextColor(Color.WHITE);b.setAllCaps(false);b.setGravity(Gravity.CENTER);b.setPadding(dp(2),dp(4),dp(2),dp(4));b.setMinWidth(0);b.setMinimumWidth(0);b.setMinHeight(0);b.setMinimumHeight(0);android.graphics.drawable.GradientDrawable background=new android.graphics.drawable.GradientDrawable();background.setColor(Color.rgb(51,65,85));background.setCornerRadius(dp(8));b.setBackground(new android.graphics.drawable.RippleDrawable(android.content.res.ColorStateList.valueOf(Color.rgb(100,116,139)),background,null));LinearLayout.LayoutParams layout=new LinearLayout.LayoutParams(0,dp(54),1);layout.setMargins(dp(3),dp(4),dp(3),dp(4));row.addView(b,layout);b.setOnClickListener(v->action.run());return b;}
 private Button iconButton(LinearLayout row,int icon,String name,Runnable action){Button b=button(row,name,action);b.setTextSize(10);android.graphics.drawable.Drawable drawable=getDrawable(icon);drawable.setBounds(0,0,dp(22),dp(22));b.setCompoundDrawables(null,drawable,null,null);b.setCompoundDrawablePadding(dp(2));b.setContentDescription(name);b.setTooltipText(name);b.getLayoutParams().height=dp(54);return b;}
 private void refresh(){if(session==null){status.setText("Controller disconnected");monitorStatus.setText("Checking monitor…");refreshSettings();return;}String summary=session.status.split("\\n",2)[0];if(!session.activePackage.isEmpty())summary=summary.replace(session.activePackage,activeAppName());status.setText(summary);boolean connected=session.external!=null,ready=session.id>=0&&!session.busy;monitorStatus.setBackgroundColor(ready?Color.rgb(6,78,59):connected?Color.rgb(113,63,18):Color.rgb(127,29,29));monitorStatus.setText(!connected?"MONITOR DISCONNECTED\nConnect an external display":(ready?"MONITOR CONNECTED · DESKTOP READY":"MONITOR CONNECTED · "+(session.busy?"STARTING / UPDATING":"DESKTOP WAITING"))+"\n"+session.external.getName()+(session.id>=0?" · "+session.width()+" × "+session.height()+"\n"+orientations[session.rotation]+" · "+session.dpi+" UI DPI":""));confirmation.setVisibility(session.awaitingConfirmation()?View.VISIBLE:View.GONE);refreshSettings();pad.invalidate();}
 @Override protected void onDestroy(){if(diagnosticsDialog!=null)diagnosticsDialog.dismiss();if(session!=null){pad.cancel();session.listener=null;}unbindService(connection);super.onDestroy();}
 @Override protected void onPause(){if(pad!=null)pad.cancel();super.onPause();}
 private void rotation(){if(session==null)return;pad.cancel();new AlertDialog.Builder(this).setTitle("Monitor orientation").setSingleChoiceItems(orientations,session.rotation,(dialog,which)->{session.rotate(which,true);dialog.dismiss();}).setNeutralButton("Save for app",(d,w)->session.rememberApp(true)).setNegativeButton("Cancel",null).show();}
 private void scrollMode(){if(session==null)return;pad.cancel();new AlertDialog.Builder(this).setTitle("Scrolling for active app").setSingleChoiceItems(new String[]{"Swipe - native touchscreen drag","Scroll - mouse wheel"},session.swipeScrolling()?0:1,(dialog,which)->{session.setSwipeScrolling(which==0);dialog.dismiss();}).setNegativeButton("Cancel",null).show();}
 private void scrollSpeed(){if(session==null)return;if(session.activePackage.isEmpty()){session.report("Launch an app first");return;}pad.cancel();new AlertDialog.Builder(this).setTitle("Scroll speed for "+activeAppName()).setSingleChoiceItems(new String[]{"Slow (20%)","Normal (50%)","Fast (100%)"},session.scrollSpeed()<.35f?0:session.scrollSpeed()<.75f?1:2,(dialog,which)->{session.prefs.edit().putFloat("scrollSpeed."+session.activePackage,new float[]{.2f,.5f,1f}[which]).apply();session.report("Scroll speed saved for active app");dialog.dismiss();}).setNegativeButton("Cancel",null).show();}
 private String activeAppName(){if(session==null||session.activePackage.isEmpty())return "No app selected";try{return getPackageManager().getApplicationLabel(getPackageManager().getApplicationInfo(session.activePackage,0)).toString();}catch(PackageManager.NameNotFoundException e){return session.activePackage;}}
 private void refreshSettings(){if(session==null){settingsStatus.setText("Controller disconnected");return;}String saved=session.prefs.contains("app."+session.activePackage)?orientations[session.prefs.getInt("app."+session.activePackage,0)]:"Session default";float speed=session.scrollSpeed();String speedName=speed<.35f?"Slow":speed<.75f?"Normal":"Fast";settingsStatus.setText("App: "+activeAppName()+"\nInput: "+(session.swipeScrolling()?"Swipe":"Wheel scroll")+"  |  Speed: "+speedName+" ("+Math.round(speed*100)+"%)\nSaved rotation: "+saved+"\nMonitor touch: "+(session.monitorTouchEnabled()?"On":"Off")+"  |  Scroll direction: "+(session.prefs.getBoolean("reverseScroll",false)?"Reversed":"Normal"));scrollMode.setText(session.swipeScrolling()?"Swipe mode":"Scroll mode");}
 private void options(){if(session==null)return;pad.cancel();List<String> names=new ArrayList<>();List<Runnable> actions=new ArrayList<>();
  if(session.needsRecovery()){names.add("Retry automatic connection");actions.add(()->session.retryDesktop());names.add("Open Shizuku");actions.add(()->{Intent launch=getPackageManager().getLaunchIntentForPackage("moe.shizuku.privileged.api");if(launch!=null)startActivity(launch);else session.report("Install Shizuku to use the desktop");});}
  names.add("Diagnostic log");actions.add(this::diagnostics);
  names.add("Display resolution and DPI");actions.add(this::displaySettings);
  names.add("Center pointer");actions.add(()->session.center());
  names.add("Pointer speed");actions.add(()->new AlertDialog.Builder(this).setTitle("Pointer speed").setItems(new String[]{"Slow","Normal","Fast"},(d,i)->{session.prefs.edit().putFloat("speed",new float[]{1,1.6f,2.5f}[i]).apply();session.report("Pointer speed changed");}).show());
  names.add("Reverse scroll direction");actions.add(()->{session.prefs.edit().putBoolean("reverseScroll",!session.prefs.getBoolean("reverseScroll",false)).apply();session.report("Scroll direction changed");});
  names.add("Reset saved monitor profile");actions.add(()->session.resetMonitor());
  names.add(session.monitorTouchEnabled()?"Monitor touch: On":"Monitor touch: Off");actions.add(()->session.setMonitorTouchEnabled(!session.monitorTouchEnabled()));
  names.add("Allow background operation");actions.add(()->{if(session.backgroundProtectionEnabled())session.report("Background operation allowed");else startActivity(new Intent(android.provider.Settings.ACTION_REQUEST_IGNORE_BATTERY_OPTIMIZATIONS,android.net.Uri.parse("package:"+getPackageName())));});
  names.add(session.id>=0||session.busy?"Stop desktop":"Resume automatic desktop");actions.add(()->{if(session.id>=0||session.busy)session.pauseDesktop();else session.retryDesktop();});
  new AlertDialog.Builder(this).setTitle("Options").setItems(names.toArray(new String[0]),(dialog,which)->actions.get(which).run()).show();
 }
 private void diagnostics(){if(session==null)return;SessionService source=session;TextView text=new TextView(this);text.setTextColor(Color.WHITE);text.setBackgroundColor(Color.rgb(15,23,42));text.setTextSize(11);text.setTypeface(Typeface.MONOSPACE);text.setTextIsSelectable(true);text.setPadding(dp(12),dp(8),dp(12),dp(8));ScrollView scroll=new ScrollView(this);scroll.addView(text);Handler handler=new Handler(Looper.getMainLooper());Runnable update=new Runnable(){public void run(){String snapshot=source.diagnosticText();if(!snapshot.contentEquals(text.getText()))text.setText(snapshot);handler.postDelayed(this,500);}};diagnosticsDialog=new AlertDialog.Builder(this).setTitle("Diagnostic log").setView(scroll).setPositiveButton("Close",null).setNeutralButton("Copy",null).setNegativeButton("Clear",null).create();diagnosticsDialog.setOnDismissListener(d->{handler.removeCallbacks(update);diagnosticsDialog=null;});diagnosticsDialog.setOnShowListener(d->{diagnosticsDialog.getButton(-3).setOnClickListener(v->{((ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("DexDroid diagnostics",source.diagnosticText()));Toast.makeText(this,"Diagnostic log copied",Toast.LENGTH_SHORT).show();});diagnosticsDialog.getButton(-2).setOnClickListener(v->{source.clearDiagnostics();text.setText(source.diagnosticText());});handler.post(update);});diagnosticsDialog.show();}
 private static class App {String name;ComponentName component;android.graphics.drawable.Drawable icon;App(String n,ComponentName c,android.graphics.drawable.Drawable i){name=n;component=c;icon=i;}}
 private void apps(){if(session==null)return;pad.cancel();PackageManager pm=getPackageManager();List<App> all=new ArrayList<>();Intent intent=new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER);Set<String> seen=new HashSet<>();for(ResolveInfo r:pm.queryIntentActivities(intent,0)){String pkg=r.activityInfo.packageName;if(pkg.equals(getPackageName())||!seen.add(pkg))continue;all.add(new App(r.loadLabel(pm).toString(),new ComponentName(pkg,r.activityInfo.name),r.loadIcon(pm)));}all.add(new App("DexDroid input test",new ComponentName(this,InputTestActivity.class),getApplicationInfo().loadIcon(pm)));
  Set<String> favorites=new HashSet<>(Arrays.asList("dev.dexdroid","dev.portraitdesk","org.mozilla.firefox","app.revanced.android.youtube","eu.kanade.tachiyomi","com.android.chrome"));all.sort((a,b)->{int priority=Boolean.compare(favorites.contains(b.component.getPackageName()),favorites.contains(a.component.getPackageName()));return priority!=0?priority:a.name.compareToIgnoreCase(b.name);});
  LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);EditText search=new EditText(this);search.setSingleLine();search.setHint("Search installed apps");root.addView(search);TextView hint=new TextView(this);hint.setText("Tap to launch · Hold for a one-time orientation");root.addView(hint);ListView list=new ListView(this);root.addView(list,new LinearLayout.LayoutParams(-1,dp(380)));List<App> filtered=new ArrayList<>(all);
  BaseAdapter adapter=new BaseAdapter(){public int getCount(){return filtered.size();}public Object getItem(int p){return filtered.get(p);}public long getItemId(int p){return p;}public View getView(int position,View reused,android.view.ViewGroup parent){App app=filtered.get(position);TextView item=new TextView(MainActivity.this);item.setText(app.name+"\n"+(session.prefs.contains("app."+app.component.getPackageName())?orientations[session.prefs.getInt("app."+app.component.getPackageName(),0)]:"Session orientation"));item.setTextSize(15);item.setPadding(dp(12),dp(8),dp(8),dp(8));app.icon.setBounds(0,0,dp(36),dp(36));item.setCompoundDrawables(app.icon,null,null,null);item.setCompoundDrawablePadding(dp(12));return item;}};list.setAdapter(adapter);
  AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Open on monitor").setView(root).setNegativeButton("Close",null).create();list.setOnItemClickListener((parent,view,position,id)->{session.launch(filtered.get(position).component,null);dialog.dismiss();});list.setOnItemLongClickListener((parent,view,position,id)->{App app=filtered.get(position);new AlertDialog.Builder(this).setTitle(app.name+" • this launch only").setItems(orientations,(d,which)->{session.launch(app.component,which);dialog.dismiss();}).show();return true;});search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){filtered.clear();String query=s.toString().toLowerCase(Locale.ROOT);for(App app:all)if(app.name.toLowerCase(Locale.ROOT).contains(query)||app.component.getPackageName().contains(query))filtered.add(app);adapter.notifyDataSetChanged();}public void afterTextChanged(android.text.Editable e){}});dialog.show();}
 private void displaySettings(){if(session==null)return;pad.cancel();session.detect();if(session.external==null){session.report("Connect an external monitor first");return;}android.view.Display.Mode mode=session.external.getMode();int nativeW=mode.getPhysicalWidth(),nativeH=mode.getPhysicalHeight();int lowerW=Math.round(nativeW*2f/3),lowerH=Math.round(nativeH*2f/3);
  LinearLayout root=new LinearLayout(this);root.setPadding(dp(16),0,dp(16),0);root.setOrientation(LinearLayout.VERTICAL);TextView info=new TextView(this);info.setText(session.capabilities());info.setTextSize(13);root.addView(info);String key=session.monitorKey();int recommendedW=session.prefs.getInt(key+".w",nativeW),recommendedH=session.prefs.getInt(key+".h",nativeH),recommendedDpi=session.prefs.getInt(key+".dpi",Geometry.recommendedDpi(Math.min(nativeW,nativeH)));
  int[][] presets={{recommendedW,recommendedH,recommendedDpi},{nativeW,nativeH,Geometry.recommendedDpi(Math.min(nativeW,nativeH))},{lowerW,lowerH,Geometry.recommendedDpi(Math.min(lowerW,lowerH))}};
  String[] names={"Recommended","Same as current output • sharp","Lower rendering load"};Spinner preset=new Spinner(this);String[] labels=new String[3];for(int i=0;i<3;i++)labels[i]=names[i]+"\n"+presets[i][0]+" × "+presets[i][1]+" • "+presets[i][2]+" UI DPI";preset.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,labels));root.addView(preset);
  EditText dimensions=new EditText(this);dimensions.setSingleLine();dimensions.setHint("Desktop width × height (e.g. 1920x1200)");root.addView(dimensions);EditText density=new EditText(this);density.setSingleLine();density.setInputType(2);density.setHint("UI DPI: 120–480");root.addView(density);preset.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onItemSelected(AdapterView<?> p,View v,int i,long id){dimensions.setText(presets[i][0]+"x"+presets[i][1]);density.setText(""+presets[i][2]);}public void onNothingSelected(AdapterView<?> p){}});
  TextView note=new TextView(this);note.setText("Different aspect ratios use Fit with bars. Dimensions swap for portrait. UI DPI controls text size, not physical monitor density.");root.addView(note);ScrollView scroll=new ScrollView(this);scroll.addView(root);AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Desktop resolution").setView(scroll).setPositiveButton("Preview",null).setNegativeButton("Cancel",null).create();dialog.setOnShowListener(d->dialog.getButton(-1).setOnClickListener(v->{try{String[] values=dimensions.getText().toString().toLowerCase(Locale.ROOT).replace("×","x").split("x");int w=Integer.parseInt(values[0].trim()),h=Integer.parseInt(values[1].trim()),dpi=Integer.parseInt(density.getText().toString());if(values.length!=2||w<480||h<480||w>4096||h>4096||dpi<120||dpi>480)throw new IllegalArgumentException();session.preview(w,h,dpi);dialog.dismiss();}catch(Exception e){dimensions.setError("Use dimensions 480–4096 and DPI 120–480");}}));dialog.show();}
 private class Pad extends View {
  private float lastX,lastY,startX,startY,startSpan,total,pinchSpan,anchorX,anchorY;
  private int fingers,kind=0;
  private boolean multitouch,pinching,swiping;
  private long down,lastFrame;
  private Paint paint=new Paint(3);
  Pad(){super(MainActivity.this);setBackgroundColor(Color.rgb(30,41,59));}
  @Override protected void onDraw(Canvas c){paint.setColor(Color.rgb(71,85,105));for(int x=dp(20);x<getWidth();x+=dp(30))for(int y=dp(20);y<getHeight();y+=dp(30))c.drawCircle(x,y,2,paint);paint.setTextSize(dp(16));paint.setColor(Color.LTGRAY);c.drawText("TOUCHPAD",dp(16),dp(30),paint);}
  private float centerX(MotionEvent e){float x=0;for(int i=0;i<e.getPointerCount();i++)x+=e.getX(i);return x/e.getPointerCount();}
  private float centerY(MotionEvent e){float y=0;for(int i=0;i<e.getPointerCount();i++)y+=e.getY(i);return y/e.getPointerCount();}
  private float span(MotionEvent e){return (float)Math.hypot(e.getX(1)-e.getX(0),e.getY(1)-e.getY(0));}
  private void pinch(int action){float max=Math.min(Math.min(anchorX,session.width()-1-anchorX),Math.min(anchorY,session.height()-1-anchorY));float half=Geometry.clamp(pinchSpan/2,1,Math.max(1,max));session.touch(action,new float[]{anchorX-half,anchorX+half},new float[]{anchorY,anchorY});}
  private void endPinch(){if(pinching&&session!=null){pinch(MotionEvent.ACTION_POINTER_UP|(1<<8));session.touch(MotionEvent.ACTION_UP,new float[]{Geometry.clamp(anchorX-Math.min(pinchSpan/2,Math.min(Math.min(anchorX,session.width()-1-anchorX),Math.min(anchorY,session.height()-1-anchorY))),0,session.width()-1)},new float[]{anchorY});}pinching=false;}
  void cancel(){if((pinching||swiping)&&session!=null)session.cancelPhoneInput();pinching=false;swiping=false;fingers=0;kind=0;multitouch=true;}
  @Override public boolean onTouchEvent(MotionEvent e){if(session==null||session.id<0||session.busy){if(session!=null&&e.getActionMasked()==MotionEvent.ACTION_DOWN)session.log("Touchpad ignored: desktop="+session.id+" busy="+session.busy);cancel();return true;}int action=e.getActionMasked();float x=centerX(e),y=centerY(e);
   if(action==MotionEvent.ACTION_DOWN){session.log("Touchpad DOWN: 1 finger");session.showTouchpadPointer();cancel();multitouch=false;lastX=startX=x;lastY=startY=y;fingers=1;total=0;down=e.getEventTime();}
   else if(action==MotionEvent.ACTION_POINTER_DOWN){endPinch();if(swiping){session.cancelPhoneInput();swiping=false;}multitouch=true;fingers=e.getPointerCount();session.log("Touchpad pointers: "+fingers+"; three-finger Back requires right swipe > "+dp(60)+" px");kind=0;lastX=startX=x;lastY=startY=y;if(fingers==2)startSpan=span(e);}
   else if(action==MotionEvent.ACTION_MOVE){float dx=x-lastX,dy=y-lastY;total+=Math.abs(dx)+Math.abs(dy);lastX=x;lastY=y;int count=e.getPointerCount();if(count==1&&!multitouch)session.move(dx*session.prefs.getFloat("speed",1.6f),dy*session.prefs.getFloat("speed",1.6f));
    else if(count==2&&fingers==2){float currentSpan=span(e);if(kind==0){if(Math.abs(currentSpan-startSpan)>dp(12)&&Math.abs(currentSpan-startSpan)>Math.hypot(x-startX,y-startY)*1.2){kind=2;anchorX=Geometry.clamp(session.cx,2,session.width()-3);anchorY=Geometry.clamp(session.cy,2,session.height()-3);pinchSpan=Math.max(2,Math.min(Math.min(session.width(),session.height())*.22f,2*Math.min(Math.min(anchorX,session.width()-1-anchorX),Math.min(anchorY,session.height()-1-anchorY))));session.touch(0,new float[]{anchorX-pinchSpan/2},new float[]{anchorY});pinch(MotionEvent.ACTION_POINTER_DOWN|(1<<8));pinching=true;session.log("Gesture recognized: pinch zoom");}else if(Math.hypot(x-startX,y-startY)>dp(10)){kind=1;session.log("Gesture recognized: two-finger "+(session.swipeScrolling()?"swipe":"wheel scroll")+" at "+Math.round(session.scrollSpeed()*100)+"%");}}
     if(e.getEventTime()-lastFrame>=16){lastFrame=e.getEventTime();if(kind==2){pinchSpan=Math.min(session.width(),session.height())*.22f*currentSpan/Math.max(1,startSpan);pinch(MotionEvent.ACTION_MOVE);}else if(kind==1){float direction=session.prefs.getBoolean("reverseScroll",false)?-1:1;if(session.swipeScrolling()){if(!swiping){anchorX=session.cx;anchorY=session.cy;session.touch(0,new float[]{anchorX},new float[]{anchorY});swiping=true;}anchorX=Geometry.clamp(anchorX+dx*2*direction*session.scrollSpeed(),1,session.width()-2);anchorY=Geometry.clamp(anchorY+dy*2*direction*session.scrollSpeed(),1,session.height()-2);session.touch(2,new float[]{anchorX},new float[]{anchorY});}else session.wheel(-dx/35*direction,-dy/35*direction);}}}
   }else if(action==MotionEvent.ACTION_POINTER_UP){if(fingers>=3){boolean recognized=x-startX>dp(60)&&Math.abs(y-startY)<Math.abs(x-startX);session.log("Three-finger Back "+(recognized?"recognized":"rejected")+": dx="+Math.round(x-startX)+" dy="+Math.round(y-startY)+" threshold="+dp(60)+" px rightward");if(recognized)session.key(KeyEvent.KEYCODE_BACK);fingers=0;}endPinch();if(swiping){session.touch(1,new float[]{anchorX},new float[]{anchorY});swiping=false;}fingers=0;}
   else if(action==MotionEvent.ACTION_UP){endPinch();if(swiping){session.touch(1,new float[]{anchorX},new float[]{anchorY});swiping=false;}if(!multitouch&&total<dp(10)&&e.getEventTime()-down<500){session.log("Gesture recognized: tap");session.click();}fingers=0;}
   else if(action==MotionEvent.ACTION_CANCEL){session.log("Touchpad gesture canceled by Android");cancel();}return true;
  }
 }
}
